package com.wanyuecity.energy.notification.service;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.fasterxml.jackson.databind.ObjectMapper;import com.wanyuecity.energy.notification.entity.*;import com.wanyuecity.energy.notification.mapper.*;import com.wanyuecity.energy.notification.provider.*;import com.wanyuecity.energy.platform.crypto.CredentialCryptoService;import com.wanyuecity.energy.platform.entity.*;import com.wanyuecity.energy.platform.mapper.*;import com.wanyuecity.energy.platform.service.MerchantNameParser;import com.wanyuecity.energy.stall.entity.Stall;import com.wanyuecity.energy.stall.mapper.StallMapper;import com.wanyuecity.energy.verification.entity.*;import com.wanyuecity.energy.verification.mapper.*;import com.wanyuecity.energy.workflow.entity.*;import com.wanyuecity.energy.workflow.mapper.*;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Slf4j(topic="webhook") @Service @RequiredArgsConstructor public class NotificationService {private final WebhookConfigMapper configMapper;private final WebhookLogMapper logMapper;private final FieldVerificationTaskMapper taskMapper;private final FieldVerificationDeviceMapper deviceMapper;private final WorkflowMapper workflowMapper;private final StallMapper stallMapper;private final DataExceptionMapper dataExceptionMapper;private final PlatformSyncBatchMapper syncBatchMapper;private final JdbcTemplate jdbc;private final CredentialCryptoService crypto;private final List<NotificationProvider> providers;private final ObjectMapper json;private final com.wanyuecity.energy.system.migration.MigrationMaintenance migrationMaintenance;@Value("${energy.public-base-url:https://auto.apperload.com}")private String publicBaseUrl;
 private static final DateTimeFormatter MESSAGE_TIME_FORMAT=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
 public void notifyVerificationCreated(Long workflowId){try{Workflow w=workflowMapper.selectById(workflowId);FieldVerificationTask task=taskMapper.selectOne(new QueryWrapper<FieldVerificationTask>().eq("workflow_id",workflowId).last("LIMIT 1"));if(w==null||task==null)return;Stall stall=stallMapper.selectById(w.getStallId());List<FieldVerificationDevice> devices=deviceMapper.selectList(new QueryWrapper<FieldVerificationDevice>().eq("verification_task_id",task.getId()));String link=publicBaseUrl.replaceAll("/$","")+"/verify/"+task.getAccessToken();String content=content(w,stall,devices,link);String event="FIELD_VERIFICATION_CREATED_"+w.getWorkflowType();NotificationMessage message=new NotificationMessage(event,workflowId,content,audit(content));for(WebhookConfig c:enabled(event))send(c,message,null);}catch(Exception e){log.error("verification notification preparation failed: workflowId={}, error={}",workflowId,e.getClass().getSimpleName());}}
 public void notifyWorkflowCompleted(Long workflowId){try{Workflow w=workflowMapper.selectById(workflowId);if(w==null)return;Stall s=stallMapper.selectById(w.getStallId());String event="WORKFLOW_COMPLETED_"+w.getWorkflowType();String merchant=n(flowMerchantName(w));String action=switch(w.getWorkflowType()==null?"":w.getWorkflowType()){case "MERCHANT_EXIT"->"撤柜";case "EXISTING_MERCHANT_ADD_STALL"->"增铺";default->"开户";};String link=publicBaseUrl.replaceAll("/$","")+"/workflow/"+w.getId();String content="### ✅ 水电费变更流程已完成\n\n**申请人**："+n(w.getApplicantName())+"\n**商户**："+merchant+"（"+n(w.getMerchantCode())+"）\n**铺位**："+(s==null?w.getStallId():n(s.getStallCode()))+"\n**办理事项**："+action+"\n**完成时间**："+formatMessageTime(w.getCompletedAt())+"\n\n> "+merchant+"商户"+action+"流程已完成。\n\n[👉 查看流程详情]("+link+")";NotificationMessage message=new NotificationMessage(event,workflowId,content,audit(content));for(WebhookConfig c:enabled(event))send(c,message,null);}catch(Exception e){log.error("workflow completion notification failed: workflowId={}, error={}",workflowId,e.getClass().getSimpleName());}}
 public void notifyDataExceptions(Long batchId){try{PlatformSyncBatch batch=syncBatchMapper.selectById(batchId);if(batch==null)return;for(String severity:List.of("WARN","ERROR","CRITICAL")){List<DataException> rows=dataExceptionMapper.selectList(new QueryWrapper<DataException>().eq("sync_batch_id",batchId).eq("severity",severity).orderByDesc("id"));if(rows.isEmpty())continue;String event="DATA_EXCEPTION_"+severity;String content=exceptionContent(batch,rows,severity);NotificationMessage message=new NotificationMessage(event,null,content,audit(content));for(WebhookConfig c:enabled(event))send(c,message,null);}}catch(Exception e){log.error("data exception notification failed: batchId={}, error={}",batchId,e.getClass().getSimpleName(),e);}}
 public void notifyInspectionTask(Long taskId,String event,String configIds){try{List<Map<String,Object>> rows=jdbc.queryForList("SELECT k.task_no,k.target_name,k.target_code,k.location_text,k.due_at,k.assignee_name,p.name plan_name FROM inspection_task k JOIN inspection_plan p ON p.id=k.plan_id WHERE k.id=?",taskId);if(rows.isEmpty())return;Map<String,Object> r=rows.get(0);String title="INSPECTION_TASK_OVERDUE".equals(event)?"巡检任务已逾期":"巡检任务即将到期";String color="INSPECTION_TASK_OVERDUE".equals(event)?"warning":"info";String link=publicBaseUrl.replaceAll("/$","")+"/inspection/tasks";String content="### 🔔 "+title+"\n\n> <font color=\""+color+"\">"+n(String.valueOf(r.get("plan_name")))+"</font>\n\n**设备**："+n(String.valueOf(r.get("target_name")))+"（"+n(String.valueOf(r.get("target_code")))+"）\n**位置**："+n(String.valueOf(r.get("location_text")))+"\n**负责人**："+n(String.valueOf(r.get("assignee_name")))+"\n**截止时间**："+String.valueOf(r.get("due_at"))+"\n\n[👉 打开巡检任务]("+link+")";NotificationMessage m=new NotificationMessage(event,null,content,audit(content));for(WebhookConfig c:selectedEnabled(event,configIds))send(c,m,null);}catch(Exception e){log.error("inspection notification failed: taskId={}, event={}, error={}",taskId,event,e.getClass().getSimpleName());}}
 private void send(WebhookConfig c,NotificationMessage m,WebhookLog existing){WebhookLog l=existing==null?new WebhookLog():existing;if(existing==null){l.setWorkflowId(m.workflowId());l.setEventType(m.eventType());l.setProvider(c.getProvider());l.setWebhookConfigId(c.getId());l.setRequestPayload(m.auditPayload());l.setRetryCount(0);}SendResult r;try{NotificationProvider p=providers.stream().filter(x->x.provider().equals(c.getProvider())).findFirst().orElseThrow();String url=crypto.decrypt(c.getWebhookUrlCiphertext(),c.getWebhookUrlIv());r=p.send(url,m);}catch(Exception e){r=new SendResult(false,null,null,e.getClass().getSimpleName());}l.setHttpStatus(r.httpStatus());l.setResponsePayload(r.response());l.setSentAt(LocalDateTime.now());l.setErrorMessage(r.error());if(r.success()){l.setSendStatus("SUCCESS");l.setNextRetryAt(null);}else{int count=(l.getRetryCount()==null?0:l.getRetryCount())+1;l.setRetryCount(count);l.setSendStatus(count>=3?"DEAD":"FAILED");l.setNextRetryAt(count>=3?null:LocalDateTime.now().plusMinutes((long)Math.pow(2,count-1)));}if(l.getId()==null)logMapper.insert(l);else logMapper.updateById(l);}
 @Scheduled(fixedDelay=60000) public void retry(){if(migrationMaintenance.isActive())return;List<WebhookLog> logs=logMapper.selectList(new QueryWrapper<WebhookLog>().eq("send_status","FAILED").lt("retry_count",3).le("next_retry_at",LocalDateTime.now()).last("LIMIT 20"));for(WebhookLog l:logs){WebhookConfig c=configMapper.selectById(l.getWebhookConfigId());if(c==null||c.getEnabled()!=1)continue;try{String content=json.readTree(l.getRequestPayload()).path("content").asText();send(c,new NotificationMessage(l.getEventType(),l.getWorkflowId(),content,l.getRequestPayload()),l);}catch(Exception e){l.setSendStatus("DEAD");l.setErrorMessage("invalid retry payload");logMapper.updateById(l);}}}
 private List<WebhookConfig> enabled(String event){return configMapper.selectList(new QueryWrapper<WebhookConfig>().eq("enabled",1).and(q->q.like("event_types",event).or().eq("event_types","FIELD_VERIFICATION_CREATED")));}private String audit(String content){try{return json.writeValueAsString(Map.of("content",content));}catch(Exception e){return "{\"content\":\"notification\"}";}}
 private List<WebhookConfig> selectedEnabled(String event,String ids){try{List<Long> selected=json.readValue(ids,new com.fasterxml.jackson.core.type.TypeReference<List<Long>>(){});if(selected!=null&&!selected.isEmpty())return configMapper.selectList(new QueryWrapper<WebhookConfig>().eq("enabled",1).in("id",selected));}catch(Exception ignored){}return enabled(event);}
 private String exceptionContent(PlatformSyncBatch batch,List<DataException> rows,String severity){String label=switch(severity){case "CRITICAL"->"严重";case "ERROR"->"错误";default->"警告";};StringBuilder b=new StringBuilder("### 🚨 异常中心告警\n\n");b.append("> <font color=\"warning\">等级：").append(label).append("</font>　共 ").append(rows.size()).append(" 条\n\n");b.append("**同步批次**：").append(n(batch.getBatchNo())).append("\n**发现时间**：").append(formatMessageTime(batch.getCompletedAt())).append("\n\n");int max=Math.min(rows.size(),10);for(int i=0;i<max;i++){DataException e=rows.get(i);b.append(i+1).append(". **").append(n(e.getTitle())).append("**\n");if(e.getPlatformDeviceId()!=null)b.append("   设备：").append(e.getPlatformDeviceId()).append("\n");String accounts=exceptionAccounts(e);if(!accounts.isBlank())b.append("   账户：").append(accounts).append("\n");if(e.getDescription()!=null&&!e.getDescription().isBlank())b.append("   ").append(shortText(e.getDescription(),100)).append("\n");}if(rows.size()>max)b.append("\n> 另有 ").append(rows.size()-max).append(" 条，请进入异常中心查看。\n");String link=publicBaseUrl.replaceAll("/$","")+"/exception?syncBatchId="+batch.getId();return b.append("\n[👉 查看异常中心](").append(link).append(")").toString();}
 private String exceptionAccounts(DataException e){if(e.getAccountNumber()!=null&&!e.getAccountNumber().isBlank()){List<String> names=jdbc.queryForList("SELECT COALESCE(NULLIF(account_name,''),account_number) FROM platform_account_current WHERE account_number=?",String.class,e.getAccountNumber());return names.isEmpty()?e.getAccountNumber():names.get(0);}if(e.getPlatformDeviceId()==null)return "";List<String> names=jdbc.queryForList("SELECT DISTINCT COALESCE(NULLIF(p.account_name,''),r.account_number) FROM platform_account_device_current r LEFT JOIN platform_account_current p ON p.account_number=r.account_number WHERE r.platform_device_id=? ORDER BY 1",String.class,e.getPlatformDeviceId());return String.join("、",names);}
 private String shortText(String value,int max){String clean=value.replace('\n',' ').replace('\r',' ');return clean.length()<=max?clean:clean.substring(0,max)+"…";}
 private String content(Workflow w,Stall s,List<FieldVerificationDevice> ds,String link){StringBuilder b=new StringBuilder("### 📋 现场设备核验任务\n");b.append("> <font color=\"info\">").append(type(w.getWorkflowType())).append("</font>　<font color=\"comment\">").append(w.getWorkflowNo()).append("</font>\n\n");b.append("**商户**：").append(w.getMerchantCode()).append(" ").append(n(flowMerchantName(w))).append("\n");b.append("**铺位**：").append(s==null?w.getStallId():s.getStallCode()).append(" ").append(s==null?"":n(s.getStallName())).append("\n");b.append("**生效时间**：").append(formatMessageTime(w.getRequestedBillingStartTime())).append("\n");b.append("**核验设备**：").append(ds.size()).append(" 台\n");if("UNBIND_AND_DISABLE".equals(w.getExpectedAccountAction()))b.append("\n> <font color=\"warning\">设备全部解绑后账户无剩余设备，请同时停用商户账户</font>\n");b.append("\n---\n**拍照要求**\n");for(int i=0;i<ds.size();i++){FieldVerificationDevice d=ds.get(i);b.append("\n").append(i+1).append(". **").append(n(d.getDeviceNameSnapshot())).append("**（").append(meterLabel(d)).append("）\n   ").append(photoRule(d)).append("\n");}return b.append("\n<font color=\"info\">请填写当前读数；三相电表还需填写倍率</font>\n\n[👉 点击进入现场核验](").append(link).append(")").toString();}private String flowMerchantName(Workflow w){if("NEW_MERCHANT".equals(w.getWorkflowType())){String entered=MerchantNameParser.extract(w.getMerchantName(),w.getMerchantCode());return entered==null?w.getMerchantName():entered;}List<String> names=jdbc.queryForList("SELECT COALESCE(NULLIF(p.user_name,''),p.account_name) FROM platform_account_current p LEFT JOIN platform_account_local_profile l ON l.account_number=p.account_number WHERE COALESCE(NULLIF(l.merchant_code,''),p.merchant_code)=? ORDER BY p.last_synced_at DESC",String.class,w.getMerchantCode());for(String source:names){String parsed=MerchantNameParser.extract(source,w.getMerchantCode());if(parsed!=null&&!parsed.isBlank())return parsed;}String stored=MerchantNameParser.extract(w.getMerchantName(),w.getMerchantCode());return stored==null?w.getMerchantName():stored;}private String formatMessageTime(LocalDateTime value){return value==null?"-":value.format(MESSAGE_TIME_FORMAT);}private String meterLabel(FieldVerificationDevice d){if("WATER".equals(d.getEnergyType()))return "水表";return "THREE_PHASE".equals(d.getMeterPhase())?"三相电表":"单相电表";}private String photoRule(FieldVerificationDevice d){if("WATER".equals(d.getEnergyType()))return "1张：表盘表号和读数须同时清晰";if("THREE_PHASE".equals(d.getMeterPhase()))return "1张：印刷电表号和读数须同时清晰；需填写电表倍率";return "2张：电表读数照片 + 电表号/序列号照片";}private String type(String s){return switch(s==null?"":s){case "NEW_MERCHANT"->"新商户开户";case "EXISTING_MERCHANT_ADD_STALL"->"已有商户增加铺位";case "MERCHANT_EXIT"->"已有商户撤柜";default->s;};}private String n(String s){return s==null||s.isBlank()?"-":s;}}
